-- ═════════════════════════════════════════════════════════════════════
-- 0070_usernames — every member has a unique @username (S-03, the owner's decision of 25 Oct: «خد قاعدة الفيسبوك في تشابه الاسماء
-- معندهمش اي قيود و بيدي في الاخر يوزر لكل واحد» — Facebook's rule). Numbered 0070 so it runs after 0040–0069 (other branches).
--   Names may be alike or identical (0039_names_rule_9 keeps only their hygiene); the USERNAME tells two members apart: the ✎ New
--   message picker offers «name · @username · company · city», the chat header and the profile say @username, and a message typed to
--   «@username» goes to that member.
--   • profiles.username (a-z 0-9 and '.', 5-30 characters, at least one letter, no dot at either end or after another) and
--     profiles.username_key — UNIQUE: no dots, small letters, and every ASCII look-alike written as one (0 / o, 1 / l / i, rn / m,
--     vv / w, cl / d: confusables.txt + tools/names/username-twins.txt), so two usernames can never draw alike. Reserved words
--     (drugbox anywhere, admin, support, help, official, moderator, team, staff, security, payments … and Drugbox's own pages and
--     channels) are refused. The rule is generated, identical in the app, by tools/names/username_rule.mjs.
--   • made at sign-up from the name (username_base: titles skipped, Latin letters without accents, Arabic as Egyptians write it —
--     tools/names/translit-ar.txt and a letter fallback), numbered when taken (ahmed.ali.2), race-free (username_assign: the unique
--     index, retried) — by an AFTER INSERT trigger, so every way a profile is made gets one; every member
--     without one gets one here (counts: RAISE NOTICE).
--   • changed ONLY through set_username() (security definer; at most 5 changes a day, the reason said in words): a browser write to
--     username / username_key is refused (profiles_username_guard), username_key is always computed here. A username given up is
--     HELD for its member for 30 days (username_holds) — nobody else can take it meanwhile, they can take it back.
--     username_available() says whether a username can be taken and why not (60 checks a minute).
--   • my_conversations() returns the partner's username (and no longer counts members of the same name — no twins any more);
--     open_candidates() lists the profiles columns as they are now (it "returns setof profiles").
-- Every new table, function and column read has its own GRANT/REVOKE (0026); RLS on every new table, with its policy. Safe to run twice.
-- ═════════════════════════════════════════════════════════════════════

-- ── 1. the rule (generated: node tools/names/username_rule.mjs --write) ──
-- >>> generated by tools/names/username_rule.mjs (confusables.txt 16.0.0, tools/names/username-twins.txt, tools/names/translit-ar.txt) — do not edit by hand
-- the key (profiles.username_key, unique): small letters, no dots, the look-alikes of confusables.txt and username-twins.txt written as one
-- (l → i, 0 → o, 1 → i, m → rri, w → vv, d → ci, n → ri)
create or replace function public.username_key(u text)
returns text language sql immutable parallel safe as $$
  select replace(replace(replace(replace(translate(replace(translate(coalesce(u, ''), 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'), '.', ''), 'l01', 'ioi'), 'm', 'rri'), 'w', 'vv'), 'd', 'ci'), 'n', 'ri')
$$;
-- is a (well-formed) username Drugbox's? the KEY is compared (0 is o, 1 is i: «adm1n.eg» is «admin.eg»), dots do not count:
--   a word of RESERVED_ANY anywhere in a dot-separated part or at either end of the username without its dots, a word of RESERVED_PART as
--   a whole part, a word of RESERVED_WHOLE as the whole username — a part or the whole also without the digits at its ends («staff2»)
create or replace function public.username_reserved(u text)
returns boolean language sql immutable parallel safe as $$
  select exists (
    select 1 from (select translate(coalesce(u, ''), 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') as l) z,
                  lateral (select public.username_key(replace(z.l, '.', '')) as k,
                                  public.username_key(regexp_replace(replace(z.l, '.', ''), '^[0-9]+|[0-9]+$', '', 'g')) as ks) y
     where y.k = any (array['about', 'accourit', 'accourits', 'aierts', 'arioriyrrious', 'api', 'careers', 'chaririei', 'charirieis', 'corripariies', 'coritact', 'cieais', 'ciirectory', 'erriaii', 'everits', 'everyorie', 'feeci', 'groups', 'irifo', 'irisights', 'jobs', 'iegai', 'iogiri', 'iogout', 'rriaii', 'rriarket', 'rriarketpiace', 'rrierribers', 'rriessages', 'rietvvork', 'rievvs', 'riotificatioris', 'riuii', 'postrriaster', 'privacy', 'profiie', 'register', 'saies', 'settirigs', 'sigriiri', 'sigriup', 'terrris', 'trairiirig', 'uriciefirieci', 'upciates', 'userriarrie', 'userriarries', 'vvebrriaster', 'acacierriy', 'heip', 'staff', 'tearri', 'systerri', 'root', 'abuse', 'trust', 'safety', 'rrioci', 'rriocis', 'ceo', 'cirugbox', 'acirriiri', 'rriocierator', 'officiai', 'support', 'payrrierit', 'verif', 'riorepiy', 'heipciesk', 'security', 'biiiirig']::text[]) or y.ks = any (array['about', 'accourit', 'accourits', 'aierts', 'arioriyrrious', 'api', 'careers', 'chaririei', 'charirieis', 'corripariies', 'coritact', 'cieais', 'ciirectory', 'erriaii', 'everits', 'everyorie', 'feeci', 'groups', 'irifo', 'irisights', 'jobs', 'iegai', 'iogiri', 'iogout', 'rriaii', 'rriarket', 'rriarketpiace', 'rrierribers', 'rriessages', 'rietvvork', 'rievvs', 'riotificatioris', 'riuii', 'postrriaster', 'privacy', 'profiie', 'register', 'saies', 'settirigs', 'sigriiri', 'sigriup', 'terrris', 'trairiirig', 'uriciefirieci', 'upciates', 'userriarrie', 'userriarries', 'vvebrriaster', 'acacierriy', 'heip', 'staff', 'tearri', 'systerri', 'root', 'abuse', 'trust', 'safety', 'rrioci', 'rriocis', 'ceo', 'cirugbox', 'acirriiri', 'rriocierator', 'officiai', 'support', 'payrrierit', 'verif', 'riorepiy', 'heipciesk', 'security', 'biiiirig']::text[])
        or exists (select 1 from unnest(array['cirugbox', 'acirriiri', 'rriocierator', 'officiai', 'support', 'payrrierit', 'verif', 'riorepiy', 'heipciesk', 'security', 'biiiirig']::text[]) a(x)
                    where starts_with(y.k, a.x) or starts_with(y.ks, a.x) or right(y.k, char_length(a.x)) = a.x or right(y.ks, char_length(a.x)) = a.x)
        or exists (select 1 from unnest(string_to_array(z.l, '.')) p(w),
                          lateral (select public.username_key(p.w) as kw, public.username_key(regexp_replace(p.w, '^[0-9]+|[0-9]+$', '', 'g')) as kws) q
                    where q.kw = any (array['heip', 'staff', 'tearri', 'systerri', 'root', 'abuse', 'trust', 'safety', 'rrioci', 'rriocis', 'ceo', 'cirugbox', 'acirriiri', 'rriocierator', 'officiai', 'support', 'payrrierit', 'verif', 'riorepiy', 'heipciesk', 'security', 'biiiirig']::text[]) or q.kws = any (array['heip', 'staff', 'tearri', 'systerri', 'root', 'abuse', 'trust', 'safety', 'rrioci', 'rriocis', 'ceo', 'cirugbox', 'acirriiri', 'rriocierator', 'officiai', 'support', 'payrrierit', 'verif', 'riorepiy', 'heipciesk', 'security', 'biiiirig']::text[])
                       or exists (select 1 from unnest(array['cirugbox', 'acirriiri', 'rriocierator', 'officiai', 'support', 'payrrierit', 'verif', 'riorepiy', 'heipciesk', 'security', 'biiiirig']::text[]) a(x) where strpos(q.kw, a.x) > 0)))
$$;
-- '' when a username may be used, else the first reason: empty, char, short, long, dot, letter, reserved (capitals are written small first)
create or replace function public.username_problem(u text)
returns text language sql immutable parallel safe as $$
  select case
    when coalesce(u, '') = '' then 'empty'
    when translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') ~ '[^a-z0-9.]' then 'char'
    when char_length(u) < 5 then 'short'
    when char_length(u) > 30 then 'long'
    when u ~ '^[.]|[.]$|[.][.]' then 'dot'
    when translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') !~ '[a-z]' then 'letter'
    when public.username_reserved(u) then 'reserved'
    else '' end
$$;
-- the sentence for a reason (the app says the same — web/src/username.js — and translates it); u is the username as typed
create or replace function public.username_message(u text, p text)
returns text language sql immutable parallel safe as $$
  select case p
    when 'empty' then 'Choose a username'
    when 'char' then format(U&'A username can only have small letters a-z, numbers 0-9 and dots \2014 remove \201C\2066%s\2069\201D', substring(translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') from '[^a-z0-9.]'))
    when 'short' then 'A username has at least 5 characters'
    when 'long' then 'A username has at most 30 characters'
    when 'dot' then 'A dot cannot start or end a username or follow another dot'
    when 'letter' then 'A username needs at least one letter'
    when 'reserved' then format(U&'\201C\2066%s\2069\201D is kept for Drugbox \2014 choose another username', translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'))
    when 'taken' then format(U&'\201C\2066%s\2069\201D is taken \2014 choose another username', translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'))
    when 'alike' then format(U&'\201C\2066%s\2069\201D reads like a username a member has (capitals, dots and look-alikes such as 0 / o and 1 / l do not count) \2014 choose another username', translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'))
    when 'held' then format(U&'\201C\2066%s\2069\201D was just given up by a member and is kept for them for 30 days \2014 choose another username', translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'))
    when 'rate' then U&'You changed your username too often today \2014 try again tomorrow'
    when 'slow' then U&'Too many tries \2014 wait a minute and try again'
    when 'signin' then 'Sign in to choose a username'
  end
$$;
-- the n-th username to try for a base: the base itself (n = 1, when it has 5 characters), else base.n — the number padded with 0 so the
-- username has 5 characters («ali» → ali.1, «om» → om.01), the base cut so it has at most 30
create or replace function public.username_candidate(b text, n int)
returns text language sql immutable parallel safe as $$
  select case when n <= 1 and char_length(b) >= 5 then left(b, 30)
              else rtrim(left(b, 29 - char_length(d)), '.') || '.' || d end
    from (select case when char_length(b) + 1 + char_length(n::text) < 5 then lpad(greatest(n, 1)::text, 4 - char_length(b), '0') else greatest(n, 1)::text end as d) z
$$;
-- made from a name: the tables (private: read by username_base as the writer)
create table if not exists private.username_ascii (ch text primary key, s text not null);
delete from private.username_ascii;
