-- one Arabic word in Latin letters: the table, «ال…» → el…, «عبد…» → abd…, else letter by letter
create or replace function public.username_ar_word(w text)
returns text language plpgsql stable parallel safe set search_path = '' as $$
declare k text := translate(w, U&'\0623\0625\0622\0671\0624\0626\0649\0629\06CC\06A9\06C0\06C3\06BE\06C1\06D5\06D2\0621', U&'\0627\0627\0627\0627\0648\064A\064A\0647\064A\0643\0647\0647\0647\0647\0647\064A'); t text; x text;
begin
  if k = '' then return ''; end if;
  select s into t from private.username_translit where ar = k; if t is not null then return t; end if;
  if char_length(k) > 2 and left(k, 2) = 'ال' then return 'el' || public.username_ar_word(substr(w, 3)); end if;
  if char_length(k) > 3 and left(k, 3) = 'عبد' then return 'abd' || public.username_ar_word(substr(w, 4)); end if;
  x := w;
  x := regexp_replace(x, U&'^\0648', 'W');
  x := regexp_replace(x, U&'^[\064A\06CC]', 'Y');
  x := translate(x, U&'\0627\0623\0625\0622\0671\0624\0626\0628\062A\062B\062C\062D\062E\062F\0630\0631\0632\0633\0634\0635\0636\0637\0638\0639\063A\0641\0642\0643\0644\0645\0646\0647\0648\064A\0649\0629\067E\0686\0698\06AF\06A9\06CC\06A4\06A8\06AD\06A2\06A7\0679\0688\0691\0695\06B5\06BA\06BE\06C1\06C0\06C2\06C3\06C6\06CE\06D2\06D3\06D5', 'aaeaaoeBT1GH2DZRZS3SDTZa4FKKLMNHoiaaP56GKiVGGFKTDRRLNHHHHaoiiea');
  x := translate(x, U&'\0621', '');
  x := regexp_replace(x, '([B-Z1-6])(?=[B-Z1-6])', '\1a', 'g');
  x := translate(x, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz');
  x := replace(x, '1', 'th');
  x := replace(x, '2', 'kh');
  x := replace(x, '3', 'sh');
  x := replace(x, '4', 'gh');
  x := replace(x, '5', 'ch');
  x := replace(x, '6', 'zh');
  return regexp_replace(x, '[^a-z]', '', 'g');
end $$;
