create or replace function public.username_base(name text)
returns text language plpgsql stable parallel safe set search_path = '' as $$
declare n text; w text; words text[] := '{}'; toks text[] := '{}'; tok text; open boolean := false; s text; r text; i int; m text[];
begin
  n := regexp_replace(public.person_name_norm(name), U&'^(?:(?:[dD][rR]|[pP][rR][oO][fF]|[eE][nN][gG]|[eE][nN][gG][rR]|[pP][hH][aA][rR][mM]|[pP][hH][aA][rR][mM][dD]|[pP][hH]|[dD]|[mM][rR]|[mM][rR][sS]|[mM][sS]|[mM][iI][sS][sS]|[dD][iI][pP][lL]|[dD][iI][pP][lL]\005C.-[iI][nN][gG]|[sS][iI][rR]|[dD][aA][mM][eE]|[hH][aA][jJ][jJ]|[hH][aA][jJ]|[hH][aA][dD][jJ]|[hH][aA][jJ][jJ][aA]|[hH][aA][jJ][jJ][aA][hH]|[sS][hH][eE][iI][kK][hH]|[sS][hH][aA][iI][kK][hH]|[sS][hH][eE][iI][kK][hH][aA]|[sS][hH][aA][iI][kK][hH][aA]|\062F|\0645|\0635|\0643|\0623|\0627|\062F\005C.\0635|\0627\005C.\062F|\0623\005C.\062F|\0643\005C.\062F|\0645\005C.\062F|\0627\0644\062D\0627\062C|\0627\0644\062D\0627\062C\0629|\0627\0644\062D\0627\062C\0647|\0627\0644\0634\064A\062E|\0627\0644\0634\064A\062E\0629|\0627\0644\0645\0647\0646\062F\0633|\0627\0644\0645\0647\0646\062F\0633\0629|\0627\0644\062F\0643\062A\0648\0631|\0627\0644\062F\0643\062A\0648\0631\0629|\0627\0644\0623\0633\062A\0627\0630|\0627\0644\0627\0633\062A\0627\0630|\0627\0644\0623\0633\062A\0627\0630\0629|\0627\0644\0627\0633\062A\0627\0630\0629)(?:[./]*[,\060C]? |[./]+)|[^ ./,\060C]{1,5}(?:[./]+[^ ./,\060C]{1,5})*[./]+[,\060C]? )+(?=.*[^ .\005C-\2019(),/\060C])', '');
