                               or translate(m[2], U&'\0623\0625\0622\0671\0624\0626\0649\0629\06CC\06A9\06C0\06C3\06BE\06C1\06D5\06D2\0621', U&'\0627\0627\0627\0627\0648\064A\064A\0647\064A\0643\0647\0647\0647\0647\0647\064A') = any (array[U&'\0645\0627\062C\0633\062A\064A\0631', U&'\062F\0643\062A\0648\0631\0627\0647', U&'\0628\0643\0627\0644\0648\0631\064A\0648\0633', U&'\062F\0628\0644\0648\0645', U&'\0644\064A\0633\0627\0646\0633']::text[]));
    n := m[1];
  end loop;
  m := regexp_match(n, U&'^([^,\060C]*[^ ,\060C]) ?[,\060C] ?([^ ,\060C].*)$');
  if m is not null then n := regexp_replace(m[2], U&'[,\060C]', ' ', 'g') || ' ' || m[1]; end if;
  n := regexp_replace(n, U&'[\03BF\03CC\039F\038C][\03C5\03CD\03A5\038E]', 'ou', 'g');
  foreach w in array regexp_split_to_array(n, '[ .,،/]+') loop
    w := replace(replace(replace(w, '-', ''), '’', ''), '''', '');
    if w = '' then continue; end if;
    if open then toks[cardinality(toks)] := toks[cardinality(toks)] || ' ' || w; else toks := toks || w; end if;
    open := translate(w, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz') = any (array['abd', 'abdel', 'abdul', 'abdal', 'abu', 'abou', 'abo', 'el', 'al', 'ibn', 'bin', 'ben', 'bint', 'om', 'umm', 'um', 'oum']) or translate(w, U&'\0623\0625\0622\0671\0624\0626\0649\0629\06CC\06A9\06C0\06C3\06BE\06C1\06D5\06D2\0621', U&'\0627\0627\0627\0627\0648\064A\064A\0647\064A\0643\0647\0647\0647\0647\0647\064A') = any (array[U&'\0639\0628\062F', U&'\0627\0628\0648', U&'\0627\0628\0646', U&'\0628\0646', U&'\0628\0646\062A', U&'\0627\0645', U&'\0627\0644']);
  end loop;
  foreach tok in array toks loop
    if tok ~ ('^[' || U&'\0600-\06FF\0750-\077F ' || ']+$') then
      select t.s into s from private.username_translit t where t.ar = translate(replace(tok, ' ', ''), U&'\0623\0625\0622\0671\0624\0626\0649\0629\06CC\06A9\06C0\06C3\06BE\06C1\06D5\06D2\0621', U&'\0627\0627\0627\0627\0648\064A\064A\0647\064A\0643\0647\0647\0647\0647\0647\064A');
      if s is null then
        select string_agg(public.username_ar_word(p.x), '' order by p.o) into s from unnest(string_to_array(tok, ' ')) with ordinality p(x, o);
      end if;
    else
      select string_agg(case when c.x ~ '[a-z]' then c.x else coalesce((select a.s from private.username_ascii a where a.ch = c.x),
                                                                 case when c.x ~ U&'[\0600-\06FF\0750-\077F]' then public.username_ar_word(c.x) else '' end) end, '' order by c.o)
        into s from unnest(regexp_split_to_array(translate(replace(tok, ' ', ''), 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'), '')) with ordinality c(x, o);
    end if;
    s := regexp_replace(coalesce(s, ''), '[^a-z0-9]', '', 'g');
    -- a word Drugbox's staff speak with (moderator, support, drugbox…) or a rude word is left out: «Dr. Maha Moderator» → maha
    if s <> '' and s <> all (array['shit', 'fuck', 'fck', 'dick', 'cock', 'cunt', 'piss', 'slut', 'whore', 'bitch', 'bastard', 'porn', 'sex', 'nazi', 'ass', 'arse', 'fag', 'rape']::text[]) and not exists (select 1 from unnest(array['cirugbox', 'acirriiri', 'rriocierator', 'officiai', 'support', 'payrrierit', 'verif', 'riorepiy', 'heipciesk', 'security', 'biiiirig']::text[]) a(x) where strpos(public.username_key(s), a.x) > 0)
      then words := words || s; end if;
  end loop;
  if cardinality(words) = 0 then return 'member'; end if;
  -- the first and the last word; when that is Drugbox's («Joe Root»: root.…), the two joined, then one of them
  foreach r in array case when cardinality(words) = 1 then array[words[1]]
                          else array[words[1] || '.' || words[cardinality(words)], words[1] || words[cardinality(words)], words[1], words[cardinality(words)]] end loop
    r := rtrim(left(r, 30), '.');
    if r ~ '[a-z]' and not public.username_reserved(r) and not public.username_reserved(public.username_candidate(r, 2)) then return r; end if;
  end loop;
  return 'member';
end $$;
