-- a browser never writes a username: only set_username() and the server (the sign-up trigger, migrations, the service role) do, and
-- the key is always the database's own
create or replace function public.profiles_username_guard() returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'UPDATE' and new.username is not distinct from old.username and new.username_key is not distinct from old.username_key then return new; end if;
  if tg_op = 'INSERT' and new.username is null and new.username_key is null then return new; end if;
  if not public.is_server_call() then
    raise exception 'Change your username in Edit Profile' using errcode = '42501', hint = 'username:rpc';
  end if;
  new.username_key := case when new.username is null then null else public.username_key(new.username) end;
  return new;
end $$;
