-- ── 4. taking a username: the unique index (set_username also locks the two keys it moves, in one order) ──
create or replace function private.username_lock(k text) returns void language sql volatile set search_path = '' as $$
  select pg_advisory_xact_lock(hashtextextended('drugbox.username:' || k, 0))
$$;
revoke all on function private.username_lock(text) from public, anon, authenticated, service_role;
grant execute on function private.username_lock(text) to service_role;

-- can member uid take the key k? not someone else's username, not held for someone else
create or replace function private.username_free(k text, uid uuid) returns boolean language sql stable set search_path = '' as $$
  select not exists (select 1 from public.profiles p where p.username_key = k and p.id <> uid)
     and not exists (select 1 from public.username_holds h where h.username_key = k and h.profile_id <> uid and h.held_until > now())
$$;
revoke all on function private.username_free(text, uuid) from public, anon, authenticated, service_role;
grant execute on function private.username_free(text, uuid) to service_role;

-- the first free username of base, base.2, base.3 … for member uid. Race-free by the unique index alone: «free» reads the profiles and
-- the holds in ONE statement (a member giving a username up changes both in one commit), and a candidate a concurrent sign-up took
-- meanwhile fails the index and the next is tried. No advisory lock here: a bulk sign-up (a seed, an import, the backfill below) runs
-- in one transaction, and a lock per username held to its end ran out of shared memory at 100,000 members (tools/scale/seed_100k.sql)
create or replace function public.username_assign(uid uuid, b text)
returns text language plpgsql security definer set search_path = '' as $$
declare n int := 1; c text; k text; tries int := 0;
begin
  if b is null or b = '' or public.username_problem(public.username_candidate(b, 2)) not in ('') then b := 'member'; end if;
  loop
    tries := tries + 1; if tries > 10000 then raise exception 'no free username for %', b; end if;
    c := public.username_candidate(b, n); k := public.username_key(c);
    if public.username_problem(c) = '' then
      if private.username_free(k, uid) then
        begin
          update public.profiles set username = c where id = uid;
          return c;
        exception when unique_violation then null;   -- taken meanwhile by a concurrent sign-up: the next candidate
        end;
      end if;
    end if;
    -- after the first two, jump past the members whose key starts with this base's (popular names: one probe, not thousands)
    if n = 2 then n := greatest(n + 1, (select count(*)::int + 1 from public.profiles p where p.username_key like replace(replace(public.username_key(b), '\', '\\'), '%', '\%') || '%'));
    else n := n + 1; end if;
  end loop;
end $$;
revoke all on function public.username_assign(uuid, text) from public, anon, authenticated, service_role;
grant execute on function public.username_assign(uuid, text) to service_role;

-- every member without a username gets one, set-based (the backfill below; a bulk import, e.g. tools/scale/seed_100k.sql, after it
-- deferred the per-row trigger): each name's username, numbered among the members whose username it would be, the oldest first; a
-- candidate another member has, holds or is given in the same pass goes through username_assign one by one. Returns how many got one.
create or replace function public.username_assign_missing() returns int language plpgsql security definer set search_path = '' as $$
declare r record; n int; m int := 0;
begin
  with k as (select p.id, p.created_at, x.b, public.username_key(x.b) as bk
               from public.profiles p,
                    lateral (select case when y.b is null or y.b = '' or public.username_problem(public.username_candidate(y.b, 2)) <> '' then 'member' else y.b end as b
                               from (select public.username_base(p.name) as b) y) x
              where p.username is null),
       c as (select k.id, public.username_candidate(k.b, (row_number() over (partition by k.bk order by k.created_at, k.id))::int) as u from k),
       d as (select c.id, c.u, public.username_key(c.u) as uk, count(*) over (partition by public.username_key(c.u)) as dup from c)
  update public.profiles p set username = d.u
    from d
   where p.id = d.id and d.dup = 1 and public.username_problem(d.u) = ''
     and not exists (select 1 from public.profiles o where o.username_key = d.uk)
     and not exists (select 1 from public.username_holds h where h.username_key = d.uk and h.held_until > now());
  get diagnostics n = row_count;
  for r in select id, name from public.profiles where username is null order by created_at, id loop
    perform public.username_assign(r.id, public.username_base(r.name)); m := m + 1;
  end loop;
  return n + m;
end $$;
revoke all on function public.username_assign_missing() from public, anon, authenticated, service_role;
grant execute on function public.username_assign_missing() to service_role;

-- every new profile gets its username (sign-up through handle_new_user, or a profile made by the server). A bulk import in ONE session
-- may defer it — set drugbox.defer_usernames = 'on', then select public.username_assign_missing() (tools/scale/seed_100k.sql: one
-- assignment per row cost ~4 ms, 100,000 members in one statement) — a browser cannot set it (PostgREST and GoTrue set no such setting)
create or replace function public.profiles_username_assign() returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.username is null and coalesce(current_setting('drugbox.defer_usernames', true), '') <> 'on' then
    perform public.username_assign(new.id, public.username_base(new.name));
  end if;
  return null;
end $$;
revoke all on function public.profiles_username_assign() from public, anon, authenticated, service_role;
grant execute on function public.profiles_username_assign() to authenticated, service_role;
drop trigger if exists trg_profiles_username_assign on public.profiles;
create trigger trg_profiles_username_assign after insert on public.profiles
  for each row execute function public.profiles_username_assign();

-- ── 5. what a member calls: is it free? take it ──
create or replace function public.username_available(p_username text)
returns jsonb language plpgsql volatile security definer set search_path = '' as $$
declare uid uuid := auth.uid(); u text; p text; k text; c public.username_checks; o text; mine text;
begin
  if uid is null then return jsonb_build_object('ok', false, 'reason', 'signin', 'message', public.username_message('', 'signin')); end if;
  insert into public.username_checks as x (profile_id, window_start, n) values (uid, now(), 1)
    on conflict (profile_id) do update set n = case when x.window_start < now() - interval '1 minute' then 1 else x.n + 1 end,
                                           window_start = case when x.window_start < now() - interval '1 minute' then now() else x.window_start end
    returning * into c;
  if c.n > 60 then return jsonb_build_object('ok', false, 'reason', 'slow', 'message', public.username_message('', 'slow')); end if;
  u := regexp_replace(btrim(coalesce(p_username, '')), '^@', '');
  p := public.username_problem(u);
  if p = '' then
    k := public.username_key(u);
    select x.username into o from public.profiles x where x.username_key = k and x.id <> uid;
    select x.username into mine from public.profiles x where x.id = uid;
    -- taken: the username itself; alike: another member's that reads the same (capitals, dots, 0 / o …) — s03-user2 (v-real1)
    if o is not null then p := case when replace(o, '.', '') = replace(translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'), '.', '') then 'taken' else 'alike' end;
    elsif exists (select 1 from public.username_holds h where h.username_key = k and h.profile_id <> uid and h.held_until > now()) then p := 'held';
    -- free, but this member cannot change it today: said now, not after Save (set_username: 5 changes a day)
    elsif mine is distinct from translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz')
      and (select count(*) from public.username_changes x where x.profile_id = uid and x.changed_at > now() - interval '1 day') >= 5 then p := 'rate'; end if;
  end if;
  return jsonb_build_object('ok', p = '', 'reason', p, 'message', case when p = '' then '' else public.username_message(u, p) end,
                            'username', translate(u, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz'));
end $$;
revoke all on function public.username_available(text) from public, anon, authenticated, service_role;
grant execute on function public.username_available(text) to authenticated, service_role;

create or replace function public.set_username(p_username text)
returns text language plpgsql volatile security definer set search_path = '' as $$
declare uid uuid := auth.uid(); u text; p text; k text; old_u text; old_k text; n int; o text;
begin
  if uid is null then raise exception '%', public.username_message('', 'signin') using errcode = '42501', hint = 'username:signin'; end if;
  u := translate(regexp_replace(btrim(coalesce(p_username, '')), '^@', ''), 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz');
  p := public.username_problem(u);
  if p <> '' then raise exception '%', public.username_message(u, p) using errcode = '23514', hint = 'username:' || p; end if;
  k := public.username_key(u);
  select x.username, x.username_key into old_u, old_k from public.profiles x where x.id = uid for update;
  if not found then raise exception '%', public.username_message('', 'signin') using errcode = '42501', hint = 'username:signin'; end if;
  if old_u = u then return u; end if;
  select count(*) into n from public.username_changes x where x.profile_id = uid and x.changed_at > now() - interval '1 day';
  if n >= 5 then raise exception '%', public.username_message(u, 'rate') using errcode = 'P0001', hint = 'username:rate'; end if;
  perform private.username_lock(x) from unnest(array[k, old_k]) x where x is not null order by x;   -- one order: no deadlock
  select x.username into o from public.profiles x where x.username_key = k and x.id <> uid;
  if o is not null then p := case when replace(o, '.', '') = replace(u, '.', '') then 'taken' else 'alike' end;
    raise exception '%', public.username_message(u, p) using errcode = 'P0001', hint = 'username:' || p; end if;
  if exists (select 1 from public.username_holds h where h.username_key = k and h.profile_id <> uid and h.held_until > now()) then
    raise exception '%', public.username_message(u, 'held') using errcode = 'P0001', hint = 'username:held'; end if;
  begin
    update public.profiles set username = u where id = uid;
  exception when unique_violation then                                                          -- a sign-up took it meanwhile
    raise exception '%', public.username_message(u, 'taken') using errcode = 'P0001', hint = 'username:taken';
  end;
  delete from public.username_holds where username_key = k;                                    -- my own hold taken back, or an expired one
  if old_k is not null and old_k <> k then
    insert into public.username_holds (username_key, username, profile_id, held_until) values (old_k, old_u, uid, now() + interval '30 days')
      on conflict (username_key) do update set username = excluded.username, profile_id = excluded.profile_id, held_until = excluded.held_until;
  end if;
  insert into public.username_changes (profile_id, old_username, new_username) values (uid, old_u, u);
  return u;
end $$;
revoke all on function public.set_username(text) from public, anon, authenticated, service_role;
grant execute on function public.set_username(text) to authenticated, service_role;

-- ── 6a. the key follows the rule: when the rule's look-alikes grow (tools/names/username-twins.txt), a username whose key it now writes
--       differently is re-keyed; when two usernames now share a key, the older member keeps theirs and the newer one is given a new
--       username made from their name (counts: RAISE NOTICE). A hold whose key changed follows it (one per key: the latest kept). ──
do $$
declare r record; rekeyed int := 0; renamed int := 0;
begin
  for r in select id, name, username from public.profiles where username is not null and username_key is distinct from public.username_key(username)
            order by created_at, id loop
    begin
      update public.profiles set username_key = public.username_key(username) where id = r.id;   -- the guard writes the database's key
      rekeyed := rekeyed + 1;
    exception when unique_violation then
      update public.profiles set username = null where id = r.id;
      perform public.username_assign(r.id, public.username_base(r.name)); renamed := renamed + 1;
    end;
  end loop;
  delete from public.username_holds h where h.username_key <> public.username_key(h.username)
     and exists (select 1 from public.username_holds g where g.username_key = public.username_key(h.username) and g.username_key <> h.username_key);
  delete from public.username_holds h where h.username_key <> public.username_key(h.username)
     and exists (select 1 from public.username_holds g where public.username_key(g.username) = public.username_key(h.username) and g.username_key <> h.username_key
                 and (g.held_until, g.username_key) > (h.held_until, h.username_key));
  update public.username_holds set username_key = public.username_key(username) where username_key <> public.username_key(username);
  raise notice 'usernames (0070): % re-keyed (the look-alikes grew), % given a new username (their key is now an older member''s)', rekeyed, renamed;
end $$;

-- ── 6. every member who has none gets one (oldest member first: the plain username goes to the first) ──
do $$
declare given int; numbered int; fallback int; total int;
begin
  given := public.username_assign_missing();
  select count(*), count(*) filter (where username ~ '[.][0-9]+$'), count(*) filter (where username ~ '^member([.][0-9]+)?$')
    into total, numbered, fallback from public.profiles;
  raise notice 'usernames (0070): % profiles, % given a username now, % numbered (the name''s username was taken), % «member…» (no letters to make one from)',
    total, given, numbered, fallback;
end $$;

-- ── 7. conversations carry the partner's username (and no longer count members of the same name) ──
drop function if exists public.my_conversations(int);
create function public.my_conversations(p_limit int default 30)
returns table (partner uuid, name text, headline text, verified boolean, avatar_url text,
               last_body text, last_at timestamptz, last_from_me boolean, unread int, company text, location text, name_needs_fix boolean,
               name_key text, created_at timestamptz, username text)
language sql stable security invoker set search_path = public as $$
  select h.partner, p.name, p.headline, p.verified, p.avatar_url, h.last_body, h.last_at, h.last_from_me, h.unread, p.company, p.location, p.name_needs_fix,
         p.name_key, p.created_at, p.username
  from public.conversation_heads h join public.profiles p on p.id = h.partner
  where h.owner = (select auth.uid())
  order by h.last_at desc
  limit least(greatest(coalesce(p_limit, 30), 1), 100)
$$;
revoke all on function public.my_conversations(int) from public, anon, authenticated, service_role;
grant execute on function public.my_conversations(int) to authenticated, service_role;

-- ── 8. open_candidates() "returns setof profiles": its column list follows the table (phone stays private — 0036) ──
do $do$
declare cols text;
begin
  select string_agg(case when column_name = 'phone' then 'null::text' else 'p.' || quote_ident(column_name) end, ', ' order by ordinal_position) into cols
    from information_schema.columns where table_schema = 'public' and table_name = 'profiles';
  execute format($f$create or replace function public.open_candidates(p_limit int default 40)
returns setof public.profiles language sql stable set search_path = public as $q$
  select %s
    from public.profiles p where p.open_to_work and p.id <> coalesce(auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid)
     and p.id <> all (coalesce((select private.blocked_parties()), '{}'::uuid[]))
   order by p.created_at desc limit least(greatest(coalesce(p_limit, 40), 1), 100)
$q$$f$, cols);
end $do$;
revoke all on function public.open_candidates(int) from public, anon, authenticated, service_role;
grant execute on function public.open_candidates(int) to authenticated, service_role;

notify pgrst, 'reload schema';
